mapper.select:
select *
from `user`
where user_name_lookup = #{userName,typeHandler=com.chinahitech.shop.utils.NameLookupTypeHandler}
order by status, user_id
limit #{limit} offset #{offset}

mapper.update:
update `user`
set password = #{password},
    modify_time = #{modifyTime}
where user_id = #{userId}
  and status >= 10

update `user`
set phone = #{phone,typeHandler=com.chinahitech.shop.utils.PhoneTypeHandler},
    phone_lookup = #{phone,typeHandler=com.chinahitech.shop.utils.PhoneLookupTypeHandler},
    modify_time = #{modifyTime}
where user_id = #{userId}
  and status >= 10

update `user`
set description = #{description},
    modify_time = #{modifyTime}
where user_id = #{userId}
  and status >= 10

update `user`
set nickname = #{nickname},
    modify_time = #{modifyTime}
where user_id = #{userId}
  and status >= 10

update `user`
set status = #{status},
    modify_time = #{modifyTime}
where user_id = #{userId}
  and status < 10
